using System.Collections.Generic;
using System.Linq;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
namespace SokobanStudio {
public static class PlayInput {
 public static bool Typing=>EventSystem.current!=null&&EventSystem.current.currentSelectedGameObject!=null&&EventSystem.current.currentSelectedGameObject.GetComponent<InputField>()!=null;
 public static Cell? Direction(){if(Input.GetKeyDown(KeyCode.W)||Input.GetKeyDown(KeyCode.UpArrow))return new Cell(0,-1);if(Input.GetKeyDown(KeyCode.D)||Input.GetKeyDown(KeyCode.RightArrow))return new Cell(1,0);if(Input.GetKeyDown(KeyCode.S)||Input.GetKeyDown(KeyCode.DownArrow))return new Cell(0,1);if(Input.GetKeyDown(KeyCode.A)||Input.GetKeyDown(KeyCode.LeftArrow))return new Cell(-1,0);return null;} public static bool Tick(GameState s){if(Typing)return false;if(Input.GetKeyDown(KeyCode.R)){s.Restart();return true;}if(Input.GetKeyDown(KeyCode.Z))return s.Undo();if(Input.GetKeyDown(KeyCode.W)||Input.GetKeyDown(KeyCode.UpArrow))return s.Move(new Cell(0,-1));if(Input.GetKeyDown(KeyCode.D)||Input.GetKeyDown(KeyCode.RightArrow))return s.Move(new Cell(1,0));if(Input.GetKeyDown(KeyCode.S)||Input.GetKeyDown(KeyCode.DownArrow))return s.Move(new Cell(0,1));if(Input.GetKeyDown(KeyCode.A)||Input.GetKeyDown(KeyCode.LeftArrow))return s.Move(new Cell(-1,0));return false;}
}
public class BoardView:MonoBehaviour {
 public RectTransform Viewport;public bool Busy{get;private set;}Camera cameraView;Material material;readonly WarehouseArt art=new WarehouseArt();Transform tiles,actors;GameObject hover,robot;Dictionary<Cell,GameObject> crates=new Dictionary<Cell,GameObject>();LevelData shown;Cell lastPlayer;int width,height;
 public void Initialize(Rect viewport){cameraView=new GameObject("Board Camera",typeof(Camera)).GetComponent<Camera>();cameraView.transform.SetParent(transform);cameraView.orthographic=true;cameraView.clearFlags=CameraClearFlags.SolidColor;cameraView.backgroundColor=StudioUI.Background;cameraView.rect=viewport;material=new Material(Shader.Find("Universal Render Pipeline/2D/Sprite-Unlit-Default"));}
 Sprite Art(string kind)=>art.Art(kind);
 GameObject Tile(Transform parent,string name,Cell c,string art,int order){var g=new GameObject(name,typeof(SpriteRenderer));g.transform.SetParent(parent,false);g.transform.localPosition=Position(c);var r=g.GetComponent<SpriteRenderer>();r.sprite=Art(art);r.sharedMaterial=material;r.sortingOrder=order;return g;}
 Vector3 Position(Cell c)=>new Vector3(c.x,-c.y,0);
 public void Show(LevelData d,GameState state=null){StopAllCoroutines();Busy=false;width=d.width;height=d.height;bool rebuild=shown!=d||state==null||!tiles;if(rebuild){StudioUI.Remove(tiles?tiles.gameObject:null);tiles=new GameObject("Board").transform;tiles.SetParent(transform);for(int y=0;y<height;y++)for(int x=0;x<width;x++){var c=new Cell(x,y);if(d.terrain[y*width+x]==Terrain.Void)continue;Tile(tiles,"Terrain",c,d.terrain[y*width+x]==Terrain.Wall?WarehouseArt.WallKey(d,c):"floor",0);if(d.goals.Contains(c))Tile(tiles,"Goal",c,"goal",1);}for(int edge=0;edge<width;edge++){var marker=Tile(tiles,"Warehouse boundary",new Cell(edge,-1),"floor",-1);marker.transform.localScale=new Vector3(.7f,.06f,1);marker.GetComponent<SpriteRenderer>().color=new Color(.3f,.4f,.5f,.3f);}shown=d;}StudioUI.Remove(actors?actors.gameObject:null);actors=new GameObject("Actors").transform;actors.SetParent(transform);crates.Clear();foreach(var c in state==null?d.boxes:state.Boxes)crates[c]=Tile(actors,"Crate",c,d.goals.Contains(c)?"docked":"crate",2);var previousPlayer=lastPlayer;lastPlayer=state==null?d.player:state.Player;robot=lastPlayer.x<0?null:Tile(actors,"Robot",lastPlayer,"robot",3);if(state!=null&&state.Moves>0)Face(new Cell(lastPlayer.x-previousPlayer.x,lastPlayer.y-previousPlayer.y));Fit();}
 public void Animate(LevelData d,GameState state){if(!robot){Show(d,state);return;}var targets=state.Boxes.ToArray();Cell? old=null,next=null;foreach(var c in crates.Keys)if(!targets.Contains(c))old=c;foreach(var c in targets)if(!crates.ContainsKey(c))next=c;GameObject box=null;if(old.HasValue&&next.HasValue){box=crates[old.Value];crates.Remove(old.Value);crates[next.Value]=box;}var playerTarget=Position(state.Player);Face(new Cell(state.Player.x-lastPlayer.x,state.Player.y-lastPlayer.y));FeedbackAudio.Play(box?"push":"move");lastPlayer=state.Player;StartCoroutine(Move(robot,playerTarget,box,next.HasValue?Position(next.Value):Vector3.zero,next.HasValue&&d.goals.Contains(next.Value)));}
 System.Collections.IEnumerator Move(GameObject player,Vector3 target,GameObject box,Vector3 boxTarget,bool goal){Busy=true;Vector3 start=player.transform.localPosition,boxStart=box?box.transform.localPosition:Vector3.zero;float t=0;while(t<.1f){t+=Time.unscaledDeltaTime;float a=Mathf.SmoothStep(0,1,t/.1f);player.transform.localPosition=Vector3.Lerp(start,target,a);if(box)box.transform.localPosition=Vector3.Lerp(boxStart,boxTarget,a);yield return null;}player.transform.localPosition=target;if(box){box.transform.localPosition=boxTarget;box.GetComponent<SpriteRenderer>().sprite=Art(goal?"docked":"crate");if(goal){FeedbackAudio.Play("goal");box.transform.localScale=Vector3.one*1.08f;yield return new WaitForSecondsRealtime(.06f);box.transform.localScale=Vector3.one;}}Busy=false;}
 void Face(Cell d){if(robot&&(d.x!=0||d.y!=0))robot.transform.localRotation=Quaternion.Euler(0,0,d.x>0?-90:d.x<0?90:d.y>0?180:0);}
 public void Blocked(Cell direction){FeedbackAudio.Play("blocked");Face(direction);if(robot&&!Busy)StartCoroutine(Bump(direction));}
 System.Collections.IEnumerator Bump(Cell d){Busy=true;Vector3 start=Position(lastPlayer);float t=0;while(t<.1f){t+=Time.unscaledDeltaTime;robot.transform.localPosition=start+new Vector3(d.x,-d.y,0)*(.07f*Mathf.Sin(t/.1f*Mathf.PI));yield return null;}robot.transform.localPosition=start;Busy=false;}
 public void Celebrate(){StartCoroutine(Celebration());}
 System.Collections.IEnumerator Celebration(){Busy=true;float t=0;while(t<.25f){t+=Time.unscaledDeltaTime;foreach(var box in crates.Values)box.transform.localScale=Vector3.one*(1+.09f*Mathf.Sin(Mathf.PI*t/.25f));yield return null;}foreach(var box in crates.Values)box.transform.localScale=Vector3.one;Busy=false;}
 void Fit(){if(!cameraView||width==0)return;if(Viewport){var corners=new Vector3[4];Viewport.GetWorldCorners(corners);cameraView.rect=new Rect(corners[0].x/Screen.width,corners[0].y/Screen.height,(corners[2].x-corners[0].x)/Screen.width,(corners[2].y-corners[0].y)/Screen.height);}cameraView.transform.position=new Vector3((width-1)/2f,-(height-1)/2f,-10);cameraView.orthographicSize=Mathf.Max((height+1)/2f,(width+1)/(2f*cameraView.aspect));}
 void LateUpdate(){Fit();}
 public bool Pick(Vector3 screen,out Cell cell){cell=default;if(!cameraView||!cameraView.pixelRect.Contains(screen))return false;var world=cameraView.ScreenToWorldPoint(screen);cell=new Cell(Mathf.FloorToInt(world.x+.5f),Mathf.FloorToInt(-world.y+.5f));return cell.x>=0&&cell.y>=0&&cell.x<width&&cell.y<height;}
 public void Hover(Cell? c){if(!hover)hover=Tile(transform,"Hover",new Cell(),"hover",10);hover.SetActive(c.HasValue);if(c.HasValue)hover.transform.localPosition=Position(c.Value);}
 void OnDestroy(){art.Dispose();if(material)Destroy(material);}
}
}

